import os
import json
import base64
from typing import Union, Dict, Any

import boto3
from botocore.config import Config
from cryptography.hazmat.primitives.ciphers.aead import AESGCM


BytesLike = Union[bytes, bytearray, memoryview]


class EnvelopeEncryptionAWSKMS:
    def __init__(self, region_name: str = None):
        self.kms = boto3.client(
            "kms",
            region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION"),
            config=Config(retries={"max_attempts": 10, "mode": "standard"}),
        )

    @staticmethod
    def _b64e(data: bytes) -> str:
        return base64.b64encode(data).decode("utf-8")

    @staticmethod
    def _b64d(data: str) -> bytes:
        return base64.b64decode(data.encode("utf-8"))

    @staticmethod
    def _to_bytes(data: Union[str, BytesLike]) -> bytes:
        if isinstance(data, str):
            return data.encode("utf-8")
        return bytes(data)

    def encrypt(
        self,
        plaintext: Union[str, BytesLike],
        kms_key_id: str,
        encryption_context: Dict[str, str] = None,
        aad: Union[str, BytesLike, None] = None,
    ) -> str:
        plaintext_bytes = self._to_bytes(plaintext)
        aad_bytes = self._to_bytes(aad) if aad is not None else None

        data_key_resp = self.kms.generate_data_key(
            KeyId=kms_key_id,
            KeySpec="AES_256",
            EncryptionContext=encryption_context or {},
        )

        plaintext_data_key = data_key_resp["Plaintext"]
        encrypted_data_key = data_key_resp["CiphertextBlob"]

        nonce = os.urandom(12)
        aesgcm = AESGCM(plaintext_data_key)
        ciphertext = aesgcm.encrypt(nonce, plaintext_bytes, aad_bytes)

        envelope = {
            "provider": "aws-kms",
            "alg": "AES-256-GCM",
            "kms_key_id": kms_key_id,
            "encrypted_data_key": self._b64e(encrypted_data_key),
            "nonce": self._b64e(nonce),
            "ciphertext": self._b64e(ciphertext),
            "encryption_context": encryption_context or {},
            "aad": self._b64e(aad_bytes) if aad_bytes is not None else None,
        }
        return json.dumps(envelope, separators=(",", ":"))

    def decrypt(self, envelope_json: str) -> bytes:
        envelope: Dict[str, Any] = json.loads(envelope_json)
        if envelope.get("provider") != "aws-kms":
            raise ValueError("Unsupported provider in envelope")

        encrypted_data_key = self._b64d(envelope["encrypted_data_key"])
        nonce = self._b64d(envelope["nonce"])
        ciphertext = self._b64d(envelope["ciphertext"])
        encryption_context = envelope.get("encryption_context") or {}
        aad_b64 = envelope.get("aad")
        aad_bytes = self._b64d(aad_b64) if aad_b64 is not None else None

        decrypt_resp = self.kms.decrypt(
            CiphertextBlob=encrypted_data_key,
            EncryptionContext=encryption_context,
        )
        plaintext_data_key = decrypt_resp["Plaintext"]

        aesgcm = AESGCM(plaintext_data_key)
        return aesgcm.decrypt(nonce, ciphertext, aad_bytes)
